import java.util.*;
import java.io.*;

public class Main {
    static List<String> process(List<String[]> ops) {
        // Each op is {"TRADE", symbol, qty}, {"TOTAL", symbol} or {"TOPK", k}
        // Return one output line per TOTAL / TOPK operation
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int q = Integer.parseInt(st.nextToken());
        List<String[]> ops = new ArrayList<>();
        for (int i = 0; i < q; i++) {
            String op = st.nextToken();
            if (op.equals("TRADE")) ops.add(new String[]{op, st.nextToken(), st.nextToken()});
            else ops.add(new String[]{op, st.nextToken()});
        }
        StringBuilder sb = new StringBuilder();
        for (String s : process(ops)) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
